import { baseURL } from '@/config/app.js'

const LEGACY_ASSET_ORIGIN = 'https://shengyuan.store'
const STATIC_FILE_PREFIX = 'https://shengyuan.store/api/miniapp/files/miniapp-static'

export function getStaticAssetUrl(localPath) {
    if (typeof localPath !== 'string' || !localPath) return localPath
    if (/^https?:\/\//i.test(localPath)) return normalizeAssetUrl(localPath)
    let normalized = localPath.replace(/\\/g, '/')
    const staticIndex = normalized.indexOf('static/')
    if (staticIndex > 0) {
        normalized = `/${normalized.slice(staticIndex)}`
    } else if (staticIndex === 0) {
        normalized = `/${normalized}`
    } else if (normalized.startsWith('/')) {
        return `${LEGACY_ASSET_ORIGIN}${normalized}`
    } else {
        return `${LEGACY_ASSET_ORIGIN}/${normalized}`
    }
    return `${STATIC_FILE_PREFIX}${normalized}`
}

function normalizeAssetUrl(url) {
    if (typeof url !== 'string') return url
    if (url.indexOf(STATIC_FILE_PREFIX) === 0) {
        return url
    }
    if (url.indexOf(LEGACY_ASSET_ORIGIN) === 0) {
        return `${baseURL}${url.slice(LEGACY_ASSET_ORIGIN.length)}`
    }
    return url
}
function normalizeAssetMap(assetMap) {
    return Object.keys(assetMap).reduce((result, key) => {
        result[key] = normalizeAssetUrl(assetMap[key])
        return result
    }, {})
}
