export function getDesignAsset(localPath) {
    if (typeof localPath === 'string' && localPath.indexOf(STATIC_FILE_PREFIX) === 0) {
        return localPath
    }
    return normalizeAssetUrl(designAssetUrls[localPath] || getStaticAssetUrl(localPath))
}

